#' Sensitivity to Unobserved Confounding
#'
#' 
#' @param data .
#' @param mode .
#' @param outcome .
#' @param treat .
#' @param covs .
#' @param estimand .
#' @param link .
#' @param mType .
#' @param mEst .
#' @param mLo .
#' @param mHi .
#' @param doRosenbaum .
#' @param k .
#' @param gammaMax .
#' @param gammaStep .
#' @param level .
#' @param plot .
#' @param showHelp .
#' @param showGuide .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$guide} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$helpText} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$notes} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$effect} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$evalue} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$rsum} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$rosen} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$rosPlot} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$effect$asDF}
#'
#' \code{as.data.frame(results$effect)}
#'
#' @export
sensobs <- function(
    data,
    mode = "data",
    outcome,
    treat,
    covs,
    estimand = "ate",
    link = "logit",
    mType = "rr",
    mEst = 1.5,
    mLo = 1.2,
    mHi = 1.9,
    doRosenbaum = TRUE,
    k = 1,
    gammaMax = 3,
    gammaStep = 0.25,
    level = 95,
    plot = TRUE,
    showHelp = FALSE,
    showGuide = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("sensobs requires jmvcore to be installed (restart may be required)")

    if ( ! missing(outcome)) outcome <- jmvcore::resolveQuo(jmvcore::enquo(outcome))
    if ( ! missing(treat)) treat <- jmvcore::resolveQuo(jmvcore::enquo(treat))
    if ( ! missing(covs)) covs <- jmvcore::resolveQuo(jmvcore::enquo(covs))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(outcome), outcome, NULL),
            `if`( ! missing(treat), treat, NULL),
            `if`( ! missing(covs), covs, NULL))


    options <- sensobsOptions$new(
        mode = mode,
        outcome = outcome,
        treat = treat,
        covs = covs,
        estimand = estimand,
        link = link,
        mType = mType,
        mEst = mEst,
        mLo = mLo,
        mHi = mHi,
        doRosenbaum = doRosenbaum,
        k = k,
        gammaMax = gammaMax,
        gammaStep = gammaStep,
        level = level,
        plot = plot,
        showHelp = showHelp,
        showGuide = showGuide)

    analysis <- sensobsClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

